                // $0a48e  cmpi.b #$6, $1a4c8.l
                {
                    const s = @as(u8, 0x6);
                    const e1: u32 = 0x1a4c8;
                    k.cmp(u8, s, k.rb(e1));
                }
                // $0a496  bgt.w $13d28
                {
                    k.cy +%= 34;
                    if (!k.fz and k.fneg == k.fv) return 0x13d28;
                }
                // $0a49a  cmpi.w #$f, (a0)
                {
                    const s = @as(u16, 0xf);
                    const e1: u32 = k.a[0];
                    k.cmp(u16, s, k.rw(e1));
                }
                // $0a49e  beq.w $1a4a4
                {
                    k.cy +%= 26;
                    if (k.fz) continue :sw 0x1a4a4;
                }
                // $0a4a2  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            0x1a4a4 => {
                // $0a4a4  cmpi.w #$11, $2(a0)
                {
                    const s = @as(u16, 0x11);
                    const e1: u32 = k.a[0] +% @as(u32, 2);
                    k.cmp(u16, s, k.rw(e1));
                }
                // $0a4aa  beq.w $1a4b0
                {
                    k.cy +%= 30;
                    if (k.fz) continue :sw 0x1a4b0;
                }
                // $0a4ae  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            0x1a4b0 => {
                // $0a4b0  addi.l #$2800, $8(a0)
                {
                    const s = @as(u32, 0x2800);
                    const e1: u32 = k.a[0] +% @as(u32, 8);
                    const r = k.rl(e1) +% s;
                    k.wl(e1, r);
                }
                // $0a4b8  addi.l #$100, $12(a0)
                {
                    const s = @as(u32, 0x100);
                    const e1: u32 = k.a[0] +% @as(u32, 18);
                    const r = k.rl(e1) +% s;
                    k.wl(e1, r);
                }
                // $0a4c0  addi.w #$8, $2(a0)
                {
                    const s = @as(u16, 0x8);
                    const e1: u32 = k.a[0] +% @as(u32, 2);
                    const r = k.add(u16, s, k.rw(e1));
                    k.ww(e1, r);
                }
                // $0a4c6  rts 
                {
                    k.cy +%= 88;
                    return k.pop32();
                }
            },
            else => return k.bad(pc),
        }
    }

};

